<template>
  <view class="page">
    <view class="month"><text @click="changeMonth(-1)">‹</text><view><b>{{ monthLabel }}</b><small>当前月在前，仅可回看历史交易日</small></view><text :class="{ disabled: !canNext }" @click="changeMonth(1)">›</text></view>
    <view class="week"><text v-for="day in ['日','一','二','三','四','五','六']" :key="day">{{ day }}</text></view>
    <view class="calendar"><view v-for="cell in days" :key="cell.key" :class="['day', { active: selectedDate === cell.date, marked: cell.count }]" @click="selectDate(cell.date)"><text>{{ cell.day }}</text><small v-if="cell.count">{{ cell.count }} 个信号</small></view></view>
    <view class="headline"><text>{{ selectedDate ? `${selectedDate.slice(4, 6)}月${selectedDate.slice(6)}日 DDE` : '请选择信号日' }}</text><button v-if="selectedDate" @click="loadDetail">刷新</button></view>
    <view v-if="rows.length" class="tabs"><text v-for="item in slots" :key="item.key" :class="{ active: activeSlot === item.key }" @click="activeSlot = item.key">{{ item.label }}（{{ slotCount(item.key) }}）</text></view>
    <view v-if="loading" class="empty">正在读取 DDE 信号…</view>
    <view v-else-if="selectedDate && !detailRows.length" class="empty">该时段暂无 DDE 信号</view>
    <scroll-view v-else class="list" scroll-x><view class="table"><view class="table-head"><text>排名</text><text>股票</text><text>强度</text><text v-for="day in 5" :key="day">T+{{ day }}</text></view><view v-for="(row, index) in detailRows" :key="`${row.stockCode}-${row.signalSlot}`" class="row" @click="openKline(row)"><text class="rank">{{ index + 1 }}</text><view class="stock"><text class="name">{{ row.stockName }}</text><text class="code">{{ row.stockCode }} · 信号价 {{ price(row.entryPrice) }}</text></view><text class="strength">{{ percent(row.mainNetRatio, true) }}</text><text v-for="day in 5" :key="day" :class="['return', returnValue(row, day) == null ? '' : returnValue(row, day) >= 0 ? 'up' : 'down']">{{ percent(returnValue(row, day)) }}</text></view></view></scroll-view>
    <view v-if="selectedDate && detailRows.length" class="note">实时收益按最新行情价计算，仅覆盖上一个交易日的 DDE 信号。</view>
  </view>
</template>

<script setup>
import { computed, ref } from "vue";
import { onShow } from "@dcloudio/uni-app";
import { getDdeCalendar, getDdeQuotes, listDdeSignals } from "@/api/stock/dde";
const now = new Date(); const cursor = ref(new Date(now.getFullYear(), now.getMonth(), 1)); const calendar = ref([]); const selectedDate = ref(""); const rows = ref([]); const liveRows = ref(new Map()); const loading = ref(false); const activeSlot = ref("morning");
const slots = [{ key: "morning", label: "早盘" }, { key: "noon", label: "午盘" }, { key: "close", label: "尾盘" }];
const monthKey = computed(() => `${cursor.value.getFullYear()}${String(cursor.value.getMonth() + 1).padStart(2, "0")}`); const monthLabel = computed(() => `${cursor.value.getFullYear()} 年 ${cursor.value.getMonth() + 1} 月`);
const today = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}`; const canNext = computed(() => cursor.value.getFullYear() < now.getFullYear() || cursor.value.getMonth() < now.getMonth());
const days = computed(() => { const first = new Date(cursor.value.getFullYear(), cursor.value.getMonth(), 1).getDay(); const count = new Date(cursor.value.getFullYear(), cursor.value.getMonth() + 1, 0).getDate(); const signals = new Map(calendar.value.map(item => [item.tradeDate, item.signalCount])); return Array.from({ length: first + count }, (_, i) => { const day = i - first + 1; const date = i < first ? "" : `${monthKey.value}${String(day).padStart(2, "0")}`; return { key: date || i, day: i < first ? "" : day, date, count: signals.get(date) || 0 }; }); });
const detailRows = computed(() => rows.value.filter(row => row.signalSlot === activeSlot.value).sort((left, right) => Number(right.mainNetRatio ?? -Infinity) - Number(left.mainNetRatio ?? -Infinity)));
const price = value => Number(value || 0).toFixed(2); const percent = (value, ratio = false) => value === null || value === undefined ? "--" : `${Number(value) >= 0 ? "+" : ""}${(Number(value) * (ratio ? 100 : 1)).toFixed(2)}%`; const slot = value => ({ morning: "早盘", noon: "午盘", close: "尾盘" })[value] || value;
function value(row) { return row.liveT1 ?? row.t1MaxReturnPct; }
function returnValue(row, day) { return day === 1 ? value(row) : row[`t${day}MaxReturnPct`]; }
function slotCount(value) { return rows.value.filter(row => row.signalSlot === value).length; }
function openKline(row) { const morningRows = rows.value.filter(item => item.signalSlot === 'morning').sort((left, right) => Number(right.mainNetRatio ?? -Infinity) - Number(left.mainNetRatio ?? -Infinity)); uni.setStorageSync('dde-kline-context', { date: selectedDate.value, selected: { code: row.stockCode, entryPrice: row.entryPrice }, rows: morningRows.map(item => ({ code: item.stockCode, name: item.stockName, entryPrice: item.entryPrice })) }); uni.navigateTo({ url: `/pages/stock/kline?code=${row.stockCode}&name=${encodeURIComponent(row.stockName)}&dde=1` }); }
async function loadCalendar() { const response = await getDdeCalendar(monthKey.value); calendar.value = response.data || []; if (!selectedDate.value && calendar.value.length) await selectDate(calendar.value[calendar.value.length - 1].tradeDate); }
async function selectDate(date) { if (!date || date > today || !calendar.value.some(item => item.tradeDate === date)) return; selectedDate.value = date; await loadDetail(); }
async function loadDetail() { if (!selectedDate.value) return; loading.value = true; try { const response = await listDdeSignals(selectedDate.value); rows.value = response.data.rows || []; activeSlot.value = rows.value[0]?.signalSlot || "morning"; liveRows.value = new Map(); if (!rows.value.length) return; const quotes = (await getDdeQuotes(rows.value.map(row => row.stockCode))).data || []; const quoteByCode = new Map(quotes.map(item => [item.stockCode, item])); const currentDate = quotes[0]?.marketDate; if (!currentDate || selectedDate.value > currentDate) return; rows.value = rows.value.map(row => { const quote = quoteByCode.get(row.stockCode); if (!quote || !row.entryPrice) return row; liveRows.value.set(row.stockCode, selectedDate.value === currentDate ? '实时收益' : 'T+1 实时收益'); return { ...row, liveT1: (Number(quote.lastPrice) / Number(row.entryPrice) - 1) * 100 }; }); } finally { loading.value = false; } }
async function changeMonth(offset) { if (offset > 0 && !canNext.value) return; cursor.value = new Date(cursor.value.getFullYear(), cursor.value.getMonth() + offset, 1); selectedDate.value = ""; rows.value = []; await loadCalendar(); }
onShow(loadCalendar);
</script>

<style scoped>
.page{min-height:100vh;background:#f5f7fb;padding:28rpx 30rpx}.month{display:flex;justify-content:space-between;align-items:center;background:#fff;border-radius:22rpx;padding:24rpx 30rpx;color:#264fc4}.month>text{font-size:50rpx}.month>text.disabled{color:#cbd3df}.month view{display:flex;flex-direction:column;align-items:center;color:#25324a}.month b{font-size:30rpx}.month small{font-size:20rpx;color:#8b96a8;margin-top:8rpx}.week,.calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:8rpx}.week{margin:26rpx 0 12rpx}.week text{text-align:center;font-size:20rpx;color:#8b96a8}.day{min-height:105rpx;padding:12rpx 8rpx;box-sizing:border-box;background:#fff;border-radius:12rpx;font-size:23rpx;color:#8a96a8}.day.marked{color:#25324a;background:#eaf0ff}.day.active{background:#315bd4;color:#fff}.day small{display:block;margin-top:10rpx;font-size:17rpx}.headline{display:flex;justify-content:space-between;align-items:center;margin:34rpx 0 16rpx;font-size:30rpx;font-weight:700;color:#17233d}.headline button{margin:0;background:#edf1ff;color:#315bd4;border:0;font-size:22rpx}.tabs{display:flex;background:#fff;border-radius:16rpx;margin-bottom:16rpx}.tabs text{flex:1;padding:20rpx 0;text-align:center;font-size:24rpx;color:#8b96a8}.tabs .active{color:#315bd4;font-weight:700;border-bottom:4rpx solid #315bd4}.list{background:#fff;border-radius:18rpx}.table{min-width:1040rpx}.table-head,.row{display:grid;grid-template-columns:58rpx 280rpx 110rpx repeat(5,118rpx);align-items:center}.table-head{height:68rpx;background:#f8faff;color:#7d8a9e;font-size:20rpx}.table-head text{text-align:center}.row{min-height:102rpx;border-top:1rpx solid #edf0f6}.rank,.strength{text-align:center;font-size:22rpx;color:#68778d}.stock{min-width:0;padding:16rpx 8rpx}.name,.code{display:block}.name{font-size:26rpx;font-weight:650;color:#25324a}.code{font-size:18rpx;color:#8b96a8;margin-top:7rpx;white-space:nowrap}.return{text-align:center;font-size:24rpx;font-weight:700}.up{color:#e44848}.down{color:#18a56c}.empty,.note{padding:48rpx 20rpx;text-align:center;border-radius:18rpx;background:#fff;color:#8b96a8;font-size:24rpx}.note{margin-top:18rpx;padding:20rpx;font-size:20rpx;line-height:1.5}
</style>
